const __inputRaw = workflowContext.actions['Format_Control'].outputs.body;
const __inputValues = Array.isArray(__inputRaw) ? __inputRaw : [__inputRaw];
const items = __inputValues.map(value =>
  value && typeof value === 'object' && 'json' in value ? value : { json: value }
);
const __unwrap = value => {
  if (Array.isArray(value)) {
    return value.map(item =>
      item && typeof item === 'object' && 'json' in item ? item.json : item
    );
  }
  return value && typeof value === 'object' && 'json' in value ? value.json : value;
};
const __node = name => {
  const output = workflowContext.actions[name]?.outputs;
  const raw = output && typeof output === 'object' && 'body' in output
    ? output.body
    : output;
  const values = Array.isArray(raw) ? raw : [raw];
  const wrapped = values.map(value =>
    value && typeof value === 'object' && 'json' in value ? value : { json: value }
  );
  return {
    item: wrapped[0],
    first: () => wrapped[0],
    last: () => wrapped[wrapped.length - 1],
    all: () => wrapped
  };
};

const $json = items[0]?.json ?? {};
const $input = {
  item: items[0],
  first: () => items[0],
  last: () => items[items.length - 1],
  all: () => items
};
const __result = (() => {
// 1) We get the raw text with $input.first() (direct JS instead of Expression)
// $input provides access to each item as n8n's global variable.
const raw = $input.first().json.text;

// 2) Regex to catch ```json … ``` block
const match = raw.match(/```json\s*([\s\S]*?)```/i);

// 3) Extract block or use full text
const jsonString = match ? match[1] : raw;

// 4) Trim + parse
const clean = jsonString.trim();
let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error(`JSON parse hatası: ${e.message}\n\nRaw içerik:\n${clean}`);
}

// 5) Return a single item output
return [{ json: parsed }];

})();
return { body: __unwrap(__result) };

